import{_ as o,l as n,o as e,c as i,v as t,p as l,x as r,d as s,i as T,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"EPT 与 NPT","description":"","frontmatter":{"title":"EPT 与 NPT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ept-npt.md","filePath":"cs/ept-npt.md","lastUpdated":1789023840000}'),E={name:"cs/ept-npt.md"};function d(A,a,c,h,_,m){const P=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="ept-与-npt" tabindex="-1">EPT 与 NPT <a class="header-anchor" href="#ept-与-npt" aria-label="Permalink to &quot;EPT 与 NPT&quot;">​</a></h1><div class="epigraph"><p>扩展页表为客机物理地址再走一层硬件翻译到宿主物理地址，避免 VMM 用影子页表同步每一条客 PTE。</p><footer>—— 据 Intel SDM 对 EPT、AMD 对 NPT/RVI 的概述；硬件辅助虚拟化的教学整理</footer></div><p><a href="/cs/trap-and-emulate">上一课</a>在软件里模拟 MMU 时，客内核改页表会频繁陷入。<a href="/cs/paging-vm">分页</a> 与 <a href="/cs/tlb-translate">TLB</a> 已有一层翻译；再加客机后变成 GPA→HPA。影子页表：VMM 把客 PTE 合成真 PTE，客写 CR3 或 PTE 都要介入。缺口是 <strong>EPT/NPT</strong>：硬件走两层页表，缺的是 EPT 违例而不是每一次客内核填表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>影子页表正确但贵：客 OS 写 PTE 是普通 store，要写保护或半虚拟化才能截获。EPT：CPU 先用客页表把 GVA→GPA，再用 EPT 把 GPA→HPA。客内核填自己的页表不必陷入。缺口不是重导宿主页表格式，而是承认第二层对象、EPT TLB、以及 shootdown 现在包括 INVEPT 一类。</p><p>本课不把 EPT 项的每个内存类型位背完。</p><p><span class="marginnote">两层都可能缺页：客缺页由客内核处理；EPT 缺页（GPA 未映射）由 VMM 处理，类似宿主的缺页路径，对象是客机物理页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VMM 为每个客机建 EPT。客机 RAM 是宿主匿名页或大页，填进 EPT。客 OS 按 <a href="/cs/demand-paging">按需调页</a> 管理自己的 GPA。VMM 可用大页覆盖客 RAM 以减 TLB 压力。设备 DMA 要用 IOMMU 指向允许的 HPA，直通时更关键。</p>',9)),(e(),l(p,null,{default:r(()=>[T(P,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20GVA%5B%22%E5%AE%A2%E8%99%9A%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20GPT%5B%22%E5%AE%A2%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20GPT%20--%3E%20GPA%5B%22%E5%AE%A2%E7%89%A9%E7%90%86%E5%9C%B0%E5%9D%80%22%5D%0A%20%20GPA%20--%3E%20EPT%5B%22EPT%2FNPT%22%5D%0A%20%20EPT%20--%3E%20HPA%5B%22%E5%AE%BF%E4%B8%BB%E7%89%A9%E7%90%86%E5%9C%B0%E5%9D%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>硬件嵌套翻译把 trap-and-emulate 的 MMU 部分从「每次填表陷入」降为「缺 EPT 时陷入」。TLB 现在缓存两层结果，容量压力更大，大页更有价值。这仍共享 CPU 微架构，不是网络。不要把侧信道写成利用课。</p><p>与容器对照：容器没有 GPA 这一层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入嵌套虚拟化（L2 的 EPT）全文。不保证所有 ARM Stage-2 细节与 x86 同名。下一课：即便 MMU 快了，设备 I/O 若逐寄存器模拟仍然慢——客机需要半虚拟化队列。</p><p>后课默认：GPA 可由硬件译到 HPA。客机块/网设备如何用共享队列通知宿主，下一课 virtio。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EPT/NPT 硬件完成 GPA→HPA，减轻影子页表。</li><li>两层缺页分给客内核与 VMM。</li><li>设备 I/O 的半虚拟化队列是 virtio 的缺口。</li><li>出处：Intel SDM（EPT）；AMD NPT；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const f=o(E,[["render",d]]);export{u as __pageData,f as default};
